-- Relay foundation: PostgreSQL 16+. Run migrations with a separate owner role.
CREATE TABLE schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, password_hash text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(email), CHECK(email=lower(email)));
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'UTC', currency text NOT NULL DEFAULT 'USD', created_at timestamptz NOT NULL DEFAULT now(), CHECK(length(name) BETWEEN 1 AND 150));
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,base_level text NOT NULL CHECK(base_level IN ('Owner','Admin','User')),active boolean NOT NULL DEFAULT true,availability text NOT NULL DEFAULT 'Available' CHECK(availability IN ('Available','Busy','On leave','Offline')),capacity int NOT NULL DEFAULT 8 CHECK(capacity BETWEEN 1 AND 1000),last_assigned_at timestamptz,UNIQUE(workspace_id,user_id),UNIQUE(id,workspace_id));
CREATE UNIQUE INDEX workspace_single_owner ON memberships(workspace_id) WHERE base_level='Owner';
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE TABLE login_attempts(key_hash text PRIMARY KEY, attempts int NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),email text NOT NULL,token_hash text NOT NULL UNIQUE,base_level text NOT NULL CHECK(base_level IN ('Admin','User')),expires_at timestamptz NOT NULL,accepted_at timestamptz,UNIQUE(id,workspace_id));
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,UNIQUE(workspace_id,name),UNIQUE(id,workspace_id));
CREATE TABLE permissions(code text PRIMARY KEY,description text NOT NULL);
INSERT INTO permissions(code,description) VALUES ('crm.view','View own CRM records'),('crm.view_all','View workspace CRM records'),('crm.create','Create CRM records'),('crm.edit','Edit permitted CRM records'),('crm.delete','Archive permitted CRM records'),('crm.export','Export permitted records'),('opportunity.value','Read opportunity amounts'),('assignment.manage','Manage lead routing'),('integration.manage','Manage provider connections'),('audit.view','Read audit history'),('workspace.manage','Manage workspace configuration');
CREATE TABLE role_permissions(workspace_id uuid NOT NULL REFERENCES workspaces(id),role_id uuid NOT NULL,permission_code text NOT NULL REFERENCES permissions(code),PRIMARY KEY(role_id,permission_code),FOREIGN KEY(role_id,workspace_id) REFERENCES roles(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE membership_roles(workspace_id uuid NOT NULL REFERENCES workspaces(id),membership_id uuid NOT NULL,role_id uuid NOT NULL,PRIMARY KEY(membership_id,role_id),FOREIGN KEY(membership_id,workspace_id) REFERENCES memberships(id,workspace_id) ON DELETE CASCADE,FOREIGN KEY(role_id,workspace_id) REFERENCES roles(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,owner_id uuid NOT NULL,archived_at timestamptz,version int NOT NULL DEFAULT 1,UNIQUE(id,workspace_id),FOREIGN KEY(owner_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),company_id uuid NOT NULL,owner_id uuid NOT NULL,name text NOT NULL,email text,phone text,opted_out boolean NOT NULL DEFAULT false,archived_at timestamptz,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id),FOREIGN KEY(company_id,workspace_id) REFERENCES companies(id,workspace_id),FOREIGN KEY(owner_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE UNIQUE INDEX contact_phone_unique ON contacts(workspace_id,phone) WHERE phone IS NOT NULL AND archived_at IS NULL;
CREATE INDEX contact_owner ON contacts(workspace_id,owner_id);
CREATE TABLE pipelines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,UNIQUE(id,workspace_id),UNIQUE(workspace_id,name));
CREATE TABLE stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),pipeline_id uuid NOT NULL,name text NOT NULL,position int NOT NULL,kind text NOT NULL DEFAULT 'open' CHECK(kind IN ('open','won','lost')),UNIQUE(id,workspace_id),UNIQUE(id,pipeline_id,workspace_id),UNIQUE(pipeline_id,name),FOREIGN KEY(pipeline_id,workspace_id) REFERENCES pipelines(id,workspace_id));
CREATE TABLE opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,owner_id uuid NOT NULL,pipeline_id uuid NOT NULL,stage_id uuid NOT NULL,name text NOT NULL,value_minor bigint NOT NULL CHECK(value_minor>=0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),close_date date,version int NOT NULL DEFAULT 1,archived_at timestamptz,UNIQUE(id,workspace_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contacts(id,workspace_id),FOREIGN KEY(owner_id,workspace_id) REFERENCES memberships(id,workspace_id),FOREIGN KEY(stage_id,pipeline_id,workspace_id) REFERENCES stages(id,pipeline_id,workspace_id));
CREATE INDEX opportunity_stage ON opportunities(workspace_id,pipeline_id,stage_id);
CREATE TABLE custom_fields(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),pipeline_id uuid NOT NULL,name text NOT NULL,type text NOT NULL CHECK(type IN ('text','number','date','dropdown','checkbox')),options jsonb NOT NULL DEFAULT '[]',archived_at timestamptz,UNIQUE(id,workspace_id),UNIQUE(id,pipeline_id,workspace_id),UNIQUE(pipeline_id,name),FOREIGN KEY(pipeline_id,workspace_id) REFERENCES pipelines(id,workspace_id));
CREATE TABLE custom_field_values(workspace_id uuid NOT NULL REFERENCES workspaces(id),field_id uuid NOT NULL,opportunity_id uuid NOT NULL,value jsonb NOT NULL,PRIMARY KEY(field_id,opportunity_id),FOREIGN KEY(field_id,workspace_id) REFERENCES custom_fields(id,workspace_id),FOREIGN KEY(opportunity_id,workspace_id) REFERENCES opportunities(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE stage_required_fields(workspace_id uuid NOT NULL REFERENCES workspaces(id),pipeline_id uuid NOT NULL,stage_id uuid NOT NULL,field_id uuid NOT NULL,PRIMARY KEY(stage_id,field_id),FOREIGN KEY(stage_id,pipeline_id,workspace_id) REFERENCES stages(id,pipeline_id,workspace_id) ON DELETE CASCADE,FOREIGN KEY(field_id,pipeline_id,workspace_id) REFERENCES custom_fields(id,pipeline_id,workspace_id));
CREATE TABLE assignment_rules(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id),ack_seconds int NOT NULL DEFAULT 600 CHECK(ack_seconds BETWEEN 10 AND 86400),idle_seconds int NOT NULL DEFAULT 86400 CHECK(idle_seconds BETWEEN 60 AND 2592000),max_escalations int NOT NULL DEFAULT 3 CHECK(max_escalations BETWEEN 1 AND 20),version int NOT NULL DEFAULT 1);
CREATE TABLE escalation_levels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),step int NOT NULL CHECK(step>0),seconds int NOT NULL CHECK(seconds BETWEEN 10 AND 86400),backup_member_id uuid,UNIQUE(workspace_id,step),FOREIGN KEY(backup_member_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,source text NOT NULL CHECK(source IN ('Manual','Website','WhatsApp','Referral')),status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','acknowledged','qualified','closed')),current_owner_id uuid,accountable_member_id uuid NOT NULL,waiting_for_assignment boolean NOT NULL DEFAULT false,first_assigned_at timestamptz,assigned_at timestamptz,acknowledgment_deadline timestamptz,acknowledged_at timestamptz,escalation_step int NOT NULL DEFAULT 0,escalation_count int NOT NULL DEFAULT 0,last_activity_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(id,workspace_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contacts(id,workspace_id),FOREIGN KEY(current_owner_id,workspace_id) REFERENCES memberships(id,workspace_id),FOREIGN KEY(accountable_member_id,workspace_id) REFERENCES memberships(id,workspace_id),CHECK((waiting_for_assignment AND current_owner_id IS NULL AND acknowledgment_deadline IS NULL) OR (NOT waiting_for_assignment AND current_owner_id IS NOT NULL)),CHECK(current_owner_id IS NULL OR current_owner_id=accountable_member_id));
CREATE INDEX leads_deadline ON leads(workspace_id,acknowledgment_deadline) WHERE status='new';
CREATE INDEX leads_owner ON leads(workspace_id,current_owner_id,status);
CREATE INDEX leads_recovery ON leads(workspace_id,last_activity_at,escalation_count);
CREATE TABLE lead_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),lead_id uuid NOT NULL,from_member_id uuid,to_member_id uuid,accountable_member_id uuid NOT NULL,reason text NOT NULL,lead_version int NOT NULL,assigned_at timestamptz NOT NULL DEFAULT now(),UNIQUE(lead_id,lead_version),FOREIGN KEY(lead_id,workspace_id) REFERENCES leads(id,workspace_id),FOREIGN KEY(from_member_id,workspace_id) REFERENCES memberships(id,workspace_id),FOREIGN KEY(to_member_id,workspace_id) REFERENCES memberships(id,workspace_id),FOREIGN KEY(accountable_member_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,opportunity_id uuid,actor_id uuid,kind text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(contact_id,workspace_id) REFERENCES contacts(id,workspace_id),FOREIGN KEY(opportunity_id,workspace_id) REFERENCES opportunities(id,workspace_id),FOREIGN KEY(actor_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE INDEX activity_timeline ON activities(workspace_id,contact_id,created_at DESC);
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,owner_id uuid NOT NULL,channel text NOT NULL,UNIQUE(id,workspace_id),UNIQUE(workspace_id,contact_id,channel),FOREIGN KEY(contact_id,workspace_id) REFERENCES contacts(id,workspace_id),FOREIGN KEY(owner_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),conversation_id uuid NOT NULL,provider_id text,body text NOT NULL,direction text NOT NULL CHECK(direction IN ('in','out')),status text NOT NULL CHECK(status IN ('queued','sent','delivered','failed','received')),error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,provider_id),FOREIGN KEY(conversation_id,workspace_id) REFERENCES conversations(id,workspace_id));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),opportunity_id uuid NOT NULL,requested_by uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),status text NOT NULL CHECK(status IN ('pending','paid','failed','expired','refunded','partially_refunded')),provider_reference text,confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id),UNIQUE(workspace_id,provider_reference),FOREIGN KEY(opportunity_id,workspace_id) REFERENCES opportunities(id,workspace_id),FOREIGN KEY(requested_by,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),payment_id uuid NOT NULL,provider_reference text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),confirmed_at timestamptz,UNIQUE(workspace_id,provider_reference),FOREIGN KEY(payment_id,workspace_id) REFERENCES payments(id,workspace_id));
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,employee_id uuid NOT NULL,title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,timezone text NOT NULL,provider_event_id text,status text NOT NULL CHECK(status IN ('pending','confirmed','failed','cancelled')),CHECK(ends_at>starts_at),UNIQUE(workspace_id,employee_id,provider_event_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contacts(id,workspace_id),FOREIGN KEY(employee_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE integrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),provider text NOT NULL CHECK(provider IN ('twilio','stripe','google','telegram')),member_id uuid,secrets_encrypted bytea,status text NOT NULL DEFAULT 'not_connected',last_success_at timestamptz,UNIQUE(id,workspace_id),FOREIGN KEY(member_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE UNIQUE INDEX workspace_provider ON integrations(workspace_id,provider) WHERE member_id IS NULL;
CREATE UNIQUE INDEX member_provider ON integrations(workspace_id,provider,member_id) WHERE member_id IS NOT NULL;
CREATE TABLE integration_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),integration_id uuid NOT NULL,provider_event_id text NOT NULL,direction text NOT NULL CHECK(direction IN ('in','out')),status text NOT NULL DEFAULT 'pending',attempts int NOT NULL DEFAULT 0,redacted_summary jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(integration_id,provider_event_id),FOREIGN KEY(integration_id,workspace_id) REFERENCES integrations(id,workspace_id));
CREATE TABLE notification_destinations(workspace_id uuid NOT NULL REFERENCES workspaces(id),member_id uuid NOT NULL,provider text NOT NULL,address text NOT NULL,PRIMARY KEY(member_id,provider),FOREIGN KEY(member_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),member_id uuid NOT NULL,lead_id uuid,kind text NOT NULL,body text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(member_id,workspace_id) REFERENCES memberships(id,workspace_id),FOREIGN KEY(lead_id,workspace_id) REFERENCES leads(id,workspace_id));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),actor_id uuid,event text NOT NULL,target_id uuid,before_state jsonb,after_state jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(actor_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE INDEX audit_lookup ON audit_logs(workspace_id,created_at DESC,event);
CREATE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit entries are append-only'; END; $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();
CREATE TABLE saved_filters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),member_id uuid NOT NULL,name text NOT NULL,filter jsonb NOT NULL,UNIQUE(member_id,name),FOREIGN KEY(member_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE dashboard_preferences(workspace_id uuid NOT NULL REFERENCES workspaces(id),member_id uuid PRIMARY KEY,visible_metrics jsonb NOT NULL DEFAULT '["leads","value","response","revenue"]',FOREIGN KEY(member_id,workspace_id) REFERENCES memberships(id,workspace_id));
CREATE TABLE tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,UNIQUE(id,workspace_id),UNIQUE(workspace_id,name));
CREATE TABLE contact_tags(workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,tag_id uuid NOT NULL,PRIMARY KEY(contact_id,tag_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contacts(id,workspace_id),FOREIGN KEY(tag_id,workspace_id) REFERENCES tags(id,workspace_id));
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),kind text NOT NULL,payload jsonb NOT NULL,dedupe_key text NOT NULL,attempts int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','done','failed')),available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,dedupe_key));
CREATE INDEX outbox_ready ON outbox_events(workspace_id,available_at) WHERE status='pending';
-- Default deny when no request/worker workspace was set. Runtime must use a non-owner, non-BYPASSRLS role.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['invitations','roles','role_permissions','membership_roles','companies','contacts','pipelines','stages','opportunities','custom_fields','custom_field_values','stage_required_fields','assignment_rules','escalation_levels','leads','lead_assignments','activities','conversations','messages','payments','refunds','appointments','integrations','integration_events','notification_destinations','notifications','audit_logs','saved_filters','dashboard_preferences','tags','contact_tags','outbox_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (workspace_id = NULLIF(current_setting(''app.workspace_id'',true),'''')::uuid) WITH CHECK (workspace_id = NULLIF(current_setting(''app.workspace_id'',true),'''')::uuid)',t); END LOOP; END $$;
INSERT INTO schema_migrations(version) VALUES('001_initial');
